import type { InputProps } from "../input.types";

import { useEffect, useRef } from "react";
import Inputmask from "inputmask";

export const useInputMask = (mask: InputProps["mask"], ref: React.RefObject<HTMLInputElement>) => {
  const maskRef = useRef<Inputmask.Instance | null>(null);

  useEffect(() => {
    if (ref.current && mask) {
      if (typeof mask === "string") {
        maskRef.current = Inputmask({ mask, showMaskOnHover: false }).mask(ref.current);
      } else if (typeof mask === "object") {
        maskRef.current = Inputmask({ showMaskOnHover: false, ...mask }).mask(ref.current);
      }
    }

    return () => {
      if (maskRef.current) {
        maskRef.current.remove();
      }
    };
  }, [mask, ref]);
};
